param(
  [Parameter(Mandatory=$true)][ValidateSet('snapshot','clean','metadata','start','children','close','alive','terminate','profiles','update','alternate','inventory','preflight')][string]$Action,
  [string]$Executable,
  [int]$AppPid = 0,
  [string]$DiagnosticPath,
  [switch]$AllowWindowInput,
  [switch]$AllowIsolatedApp
)
$ErrorActionPreference = 'Stop'
if (!$AllowIsolatedApp -or $env:GITHUB_ACTIONS -ne 'true' -or $env:RUNNER_ENVIRONMENT -ne 'github-hosted' -or $env:RUNNER_OS -ne 'Windows' -or $env:GITHUB_REPOSITORY -ne 'Sonderjyf/mihomo-route-agent') {
  throw 'App helper is restricted to an explicitly approved disposable hosted Windows guest'
}
if ($Action -eq 'clean') {
  if (@(Get-Process -Name FlClash,FlClashCore,FlClashHelperService -ErrorAction SilentlyContinue).Count -ne 0) { throw 'Guest already has an app/core/helper process' }
  if (@(Get-NetTCPConnection -State Listen | Where-Object {$_.LocalPort -in @(9090,17891,18765,18766)}).Count -ne 0) { throw 'Guest fixture port is occupied' }
  'true'; exit
}
if ($Action -eq 'snapshot') {
  $inet = Get-ItemProperty -LiteralPath 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings'
  $dns = @(Get-DnsClientServerAddress | Sort-Object InterfaceIndex,AddressFamily | Select-Object InterfaceIndex,AddressFamily,ServerAddresses)
  $routes = @(Get-NetRoute | Where-Object {$_.DestinationPrefix -in @('0.0.0.0/0','::/0','198.18.0.0/15','198.19.0.0/16')} | Sort-Object DestinationPrefix,InterfaceIndex,NextHop | Select-Object DestinationPrefix,InterfaceIndex,NextHop,RouteMetric)
  [ordered]@{proxy=@{enable=$inet.ProxyEnable;server=$inet.ProxyServer;override=$inet.ProxyOverride;pac=$inet.AutoConfigURL};winhttp=@(netsh winhttp show proxy);dns=$dns;routes=$routes;adapters=@(Get-NetAdapter -IncludeHidden | Sort-Object InterfaceIndex | Select-Object InterfaceIndex,Name,Status)} | ConvertTo-Json -Depth 8 -Compress
  exit
}
if ($Action -eq 'metadata') {
  $info = [Diagnostics.FileVersionInfo]::GetVersionInfo($Executable)
  if ($info.CompanyName.Trim() -ne 'com.follow' -or $info.ProductName.Trim() -ne 'clash') { throw 'Unexpected application-support path metadata' }
  @{company=$info.CompanyName.Trim();product=$info.ProductName.Trim();roaming=[Environment]::GetFolderPath('ApplicationData')} | ConvertTo-Json -Compress
  exit
}
if ($Action -eq 'inventory') {
  $paths=@($Executable,(Join-Path (Split-Path -Parent $Executable) 'FlClashCore.exe'))
  $processes=@(Get-CimInstance Win32_Process | Where-Object {$_.ExecutablePath -in $paths} | Select-Object ProcessId,ParentProcessId,ExecutablePath)
  $ids=@($processes | ForEach-Object {$_.ProcessId})
  $tcp=@(Get-NetTCPConnection -State Listen | Where-Object {$_.OwningProcess -in $ids -or $_.LocalPort -in @(9090,17891,18765,18766)} | Select-Object LocalAddress,LocalPort,OwningProcess)
  $udp=@(Get-NetUDPEndpoint | Where-Object {$_.OwningProcess -in $ids -or $_.LocalPort -in @(9090,17891,18765,18766)} | Select-Object LocalAddress,LocalPort,OwningProcess)
  @{processes=$processes;tcp_listeners=$tcp;udp_endpoints=$udp} | ConvertTo-Json -Depth 5 -Compress
  exit
}
if ($Action -eq 'preflight') {
  Add-Type -Path (Join-Path $PSScriptRoot 'flclash_window.cs')
  . "$PSScriptRoot/flclash_pointer.ps1"
  $session=(Get-Process -Id $PID).SessionId
  $state=[ordered]@{interactive=[Environment]::UserInteractive;session=$session;active_session=[AppWindowEvidence]::ActiveSession($session);input_desktop=[AppWindowEvidence]::InputDesktop();english_ocr=$false;ready=$false}
  try {$null=New-EnglishOcrEngine;$state.english_ocr=$true} catch {$state.ocr_error=$_.Exception.Message}
  $state.ready=$state.interactive -and $state.active_session -and $state.input_desktop -ceq 'WinSta0/Default' -and $state.english_ocr
  $state | ConvertTo-Json -Compress
  exit
}
if ($Action -eq 'start') {
  $p = Start-Process -FilePath $Executable -WorkingDirectory (Split-Path -Parent $Executable) -WindowStyle Hidden -PassThru
  @{pid=$p.Id} | ConvertTo-Json -Compress
  exit
}
if ($Action -eq 'children') {
  $children = @(Get-CimInstance Win32_Process | Where-Object {$_.ParentProcessId -eq $AppPid -and $_.ExecutablePath -eq $Executable} | Select-Object ProcessId,ExecutablePath)
  ConvertTo-Json -InputObject $children -Compress
  exit
}
$p = Get-Process -Id $AppPid -ErrorAction SilentlyContinue
if (!$p) { if($Action -eq 'alive') { 'false'; exit }; throw 'Owned app process is absent' }
if ($p.Path -ne $Executable) { throw 'Recorded PID no longer belongs to the supplied executable' }
if ($Action -eq 'alive') { 'true'; exit }
if ($Action -eq 'terminate') { Stop-Process -Id $AppPid -Force; 'true'; exit }
if ($Action -eq 'close') { if(!$p.CloseMainWindow()){throw 'No application close handler'}; 'true'; exit }
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
. "$PSScriptRoot/flclash_ui_policy.ps1"
Add-Type -AssemblyName System.Drawing
Add-Type -Path (Join-Path $PSScriptRoot 'flclash_window.cs')
$name = if($Action -eq 'profiles') {'Profiles'} else {'Update'}
$diagnostic = [ordered]@{action=$Action;pid=$AppPid;label=$name;tree=@();accessibility_requests=@();semantics_enabled='unknown';screenshot_status='not_attempted'}
$root=$null
. "$PSScriptRoot/flclash_pointer.ps1"
function Get-AppTree($Root) {
  $queue=[Collections.Generic.Queue[object]]::new()
  $queue.Enqueue($Root)
  $result=@()
  $walker=[Windows.Automation.TreeWalker]::RawViewWalker
  while($queue.Count -gt 0 -and $result.Count -lt 256) {
    $element=$queue.Dequeue()
    $current=$element.Current
    $pattern=$null
    $invoke=$element.TryGetCurrentPattern([Windows.Automation.InvokePattern]::Pattern,[ref]$pattern)
    $result += [pscustomobject]@{Name=$current.Name;ProcessId=$current.ProcessId;Enabled=$current.IsEnabled;Offscreen=$current.IsOffscreen;Invoke=$invoke;Class=$current.ClassName;Type=$current.ControlType.ProgrammaticName;Patterns=@($element.GetSupportedPatterns() | ForEach-Object {$_.ProgrammaticName});Element=$element}
    $child=$walker.GetFirstChild($element)
    while($null -ne $child -and $queue.Count -lt 256) { $queue.Enqueue($child);$child=$walker.GetNextSibling($child) }
  }
  return $result
}
try {
  if (!$AllowWindowInput) {throw 'UIA-only navigation is blocked for this release; explicit --allow-window-input is required'}
  $p.Refresh()
  if ($p.MainWindowHandle -eq 0) {throw 'no owned application window'}
  $handle=$p.MainWindowHandle
  $root=[Windows.Automation.AutomationElement]::FromHandle($handle)
  $records=@(Get-AppTree $root)
  $diagnostic.tree=@($records | Select-Object Name,ProcessId,Enabled,Offscreen,Invoke,Class,Type,Patterns)
  $result=Invoke-OwnedPointerAction $handle $AppPid $Action $DiagnosticPath $diagnostic
  $result | ConvertTo-Json -Depth 6 -Compress
  exit
} catch {
  $diagnostic.error=$_.Exception.Message
  try {
    if ($null -ne $root) {
      $rect=$root.Current.BoundingRectangle
      if($rect.Width -gt 0 -and $rect.Height -gt 0 -and $rect.Width -le 1920 -and $rect.Height -le 1440) {
        $bitmap=[Drawing.Bitmap]::new([int]$rect.Width,[int]$rect.Height)
        try {
          $graphics=[Drawing.Graphics]::FromImage($bitmap)
          try { $dc=$graphics.GetHdc(); try { $ok=[AppWindowEvidence]::PrintWindow($handle,$dc,2) } finally {$graphics.ReleaseHdc($dc)} } finally {$graphics.Dispose()}
          $stream=[IO.MemoryStream]::new()
          try {
            $bitmap.Save($stream,[Drawing.Imaging.ImageFormat]::Png)
            if($ok -and $stream.Length -le 524288) {
              $diagnostic.screenshot_png_base64=[Convert]::ToBase64String($stream.ToArray())
              $diagnostic.screenshot_status='captured_owned_window_not_verified_nonblank'
            } else { $diagnostic.screenshot_status='unsupported_or_oversized' }
          } finally {$stream.Dispose()}
        } finally {$bitmap.Dispose()}
      } else {$diagnostic.screenshot_status='unsupported_dimensions'}
    }
  } catch { $diagnostic.screenshot_status='capture_failed: '+$_.Exception.Message }
  if($DiagnosticPath) { $diagnostic | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $DiagnosticPath -Encoding utf8 }
  throw "blocked_gui_automation: $($diagnostic.error)"
}

# Loaded only by the guarded guest helper; defining these functions performs no input.
function Get-OwnedWindowState($Handle, [int]$OwnerPid) {
  [uint32]$actual=0
  $null=[AppWindowEvidence]::GetWindowThreadProcessId($Handle,[ref]$actual)
  $rect=[AppWindowEvidence+Rect]::new()
  if(![AppWindowEvidence]::GetWindowRect($Handle,[ref]$rect)){throw 'owned window rectangle unavailable'}
  $class=[Text.StringBuilder]::new(128)
  $null=[AppWindowEvidence]::GetClassName($Handle,$class,128)
  $session=(Get-Process -Id $OwnerPid).SessionId
  return @{Pid=$actual;Class=$class.ToString();Left=$rect.Left;Top=$rect.Top;Width=($rect.Right-$rect.Left);Height=($rect.Bottom-$rect.Top);Dpi=[AppWindowEvidence]::GetDpiForWindow($Handle);Visible=[AppWindowEvidence]::IsWindowVisible($Handle);Minimized=[AppWindowEvidence]::IsIconic($Handle);Foreground=([AppWindowEvidence]::GetForegroundWindow() -eq $Handle);Interactive=[Environment]::UserInteractive;ActiveSession=([AppWindowEvidence]::ActiveSession($session) -and $session -eq (Get-Process -Id $PID).SessionId);Desktop=[AppWindowEvidence]::InputDesktop()}
}

function Get-OwnedBitmap($Handle) {
  $bitmap=[Drawing.Bitmap]::new(680,580)
  $graphics=[Drawing.Graphics]::FromImage($bitmap)
  try {
    $dc=$graphics.GetHdc()
    try {$ok=[AppWindowEvidence]::PrintWindow($Handle,$dc,2)} finally {$graphics.ReleaseHdc($dc)}
  } finally {$graphics.Dispose()}
  if(!$ok){$bitmap.Dispose();throw 'owned PrintWindow failed'}
  return $bitmap
}

function Wait-WinRT($Operation, [type]$ResultType) {
  $method=[System.WindowsRuntimeSystemExtensions].GetMethods() | Where-Object {
    $_.Name -eq 'AsTask' -and $_.IsGenericMethodDefinition -and $_.GetParameters().Count -eq 1 -and
    $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1'
  } | Select-Object -First 1
  $task=$method.MakeGenericMethod($ResultType).Invoke($null,@($Operation))
  if(!$task.Wait(5000)){throw 'local OCR operation timed out'}
  return $task.Result
}

function Read-OwnedOcr($Handle, $Path, $Engine) {
  $bitmap=Get-OwnedBitmap $Handle
  try {$bitmap.Save($Path,[Drawing.Imaging.ImageFormat]::Png)} finally {$bitmap.Dispose()}
  $file=Wait-WinRT ([Windows.Storage.StorageFile]::GetFileFromPathAsync($Path)) ([Windows.Storage.StorageFile])
  $stream=Wait-WinRT ($file.OpenReadAsync()) ([Windows.Storage.Streams.IRandomAccessStreamWithContentType])
  try {
    $decoder=Wait-WinRT ([Windows.Graphics.Imaging.BitmapDecoder]::CreateAsync($stream)) ([Windows.Graphics.Imaging.BitmapDecoder])
    $software=Wait-WinRT ($decoder.GetSoftwareBitmapAsync()) ([Windows.Graphics.Imaging.SoftwareBitmap])
    try {$result=Wait-WinRT ($Engine.RecognizeAsync($software)) ([Windows.Media.Ocr.OcrResult])} finally {$software.Dispose()}
  } finally {$stream.Dispose()}
  $words=@()
  foreach($line in $result.Lines){foreach($word in $line.Words){
    $r=$word.BoundingRect
    $words+=@{Text=$word.Text;X=$r.X;Y=$r.Y;Width=$r.Width;Height=$r.Height}
    if($words.Count -gt 300){throw 'unexpected OCR volume'}
  }}
  return $words
}

function Assert-ToggleTemplate($Handle) {
  $path=Join-Path $PSScriptRoot '../evidence/windows-flclash-app-window-2026-10-08.png'
  $sha=[Security.Cryptography.SHA256]::Create()
  try {$hash=[BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes($path))).Replace('-','')} finally {$sha.Dispose()}
  if($hash -ne '857b67b9e64987206a5bbfd537b125f3f46648d42922ac44faadfac7ba9ee546'){throw 'reference screenshot changed'}
  $reference=[Drawing.Bitmap]::new($path)
  $actual=Get-OwnedBitmap $Handle
  try {
    $bad=0
    for($x=18;$x -lt 46;$x++){for($y=45;$y -lt 75;$y++){
      $a=$actual.GetPixel($x,$y);$b=$reference.GetPixel($x,$y)
      if([Math]::Abs([int]$a.R-$b.R) -gt 10 -or [Math]::Abs([int]$a.G-$b.G) -gt 10 -or [Math]::Abs([int]$a.B-$b.B) -gt 10){$bad++}
    }}
    if($bad -gt 8){throw 'sidebar toggle visual anchor differs from observed release'}
  } finally {$reference.Dispose();$actual.Dispose()}
}

function Assert-UpdateTemplate($Bitmap) {
  # Pinned 0.8.99 source: Profiles actions are sync then sort in a two-button group.
  # Recorded owned-window screenshot at 680x580/96 DPI, neutral pointer position.
  $path=Join-Path $PSScriptRoot '../evidence/windows-flclash-profiles-2026-10-08.png'
  $sha=[Security.Cryptography.SHA256]::Create()
  try {$hash=[BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes($path))).Replace('-','')} finally {$sha.Dispose()}
  if($hash -ne 'afd40956a94ce4d9c1e7a06c70ad99a5c88c0763c52ca11b3df6a6109719c583'){throw 'Profiles reference screenshot changed'}
  if($Bitmap.Width -ne 680 -or $Bitmap.Height -ne 580){throw 'unsupported Profiles image dimensions'}
  $reference=[Drawing.Bitmap]::new($path)
  try {
    $bad=0
    for($x=572;$x -lt 652;$x++){for($y=45;$y -lt 85;$y++){
      $a=$Bitmap.GetPixel($x,$y);$b=$reference.GetPixel($x,$y)
      if([Math]::Abs([int]$a.R-$b.R) -gt 10 -or [Math]::Abs([int]$a.G-$b.G) -gt 10 -or [Math]::Abs([int]$a.B-$b.B) -gt 10){$bad++}
    }}
    if($bad -gt 8){throw "Update/sort toolbar visual anchor differs: $bad pixels"}
    return @{reference_sha256=$hash.ToLowerInvariant();box=@(572,45,652,85);different_pixels=$bad;target=@{X=592;Y=65};identity='sync then sort, pinned Profiles toolbar'}
  } finally {$reference.Dispose()}
}

function Send-OwnedPointer($Handle, [int]$OwnerPid, $Origin, [int]$X, [int]$Y, [bool]$Click, $Diagnostic) {
  $state=Get-OwnedWindowState $Handle $OwnerPid
  Assert-PointerWindow $state $OwnerPid
  if($state.Left -ne $Origin.Left -or $state.Top -ne $Origin.Top){throw 'window moved during targeting'}
  if($X -lt 8 -or $X -ge 672 -or $Y -lt 33 -or $Y -ge 572){throw 'target outside owned app content'}
  $point=[AppWindowEvidence+Point]::new(($state.Left+$X),($state.Top+$Y))
  $child=[AppWindowEvidence]::WindowFromPoint($point)
  [uint32]$childOwner=0
  $null=[AppWindowEvidence]::GetWindowThreadProcessId($child,[ref]$childOwner)
  $class=[Text.StringBuilder]::new(128);$null=[AppWindowEvidence]::GetClassName($child,$class,128)
  if($childOwner -ne $OwnerPid -or $class.ToString() -cne 'FLUTTERVIEW'){throw 'target is occluded or not owned Flutter view'}
  $receipt=[AppWindowEvidence]::Pointer($Handle,$child,$point.X,$point.Y,$Click)
  $Diagnostic.pointer_events+=@{window_target=@{X=$X;Y=$Y};screen=$receipt.Screen;client=$receipt.Client;observed=$receipt.Observed;clicked=$receipt.Clicked}
}

function Invoke-OwnedPointerAction($Handle, [int]$OwnerPid, $Action, $DiagnosticPath, $Diagnostic) {
  if(!$DiagnosticPath){throw 'window input requires a diagnostic output path'}
  $Diagnostic.pointer_events=@()
  $before=Get-OwnedWindowState $Handle $OwnerPid
  $Diagnostic.pointer_window=$before
  $precheck=$before.Clone();$precheck.Foreground=$true
  Assert-PointerWindow $precheck $OwnerPid
  $engine=New-EnglishOcrEngine
  $null=[AppWindowEvidence]::SetForegroundWindow($Handle)
  Start-Sleep -Milliseconds 200
  $origin=Get-OwnedWindowState $Handle $OwnerPid
  $Diagnostic.pointer_window=$origin
  Assert-PointerWindow $origin $OwnerPid
  $imagePath=[IO.Path]::ChangeExtension($DiagnosticPath,'.ocr.png')
  $words=@(Read-OwnedOcr $Handle $imagePath $engine);$Diagnostic.last_ocr=$words
  $title=Select-OcrWord $words 'Profiles' @(60,35,380,90)
  if($Action -eq 'profiles') {
    if($null -eq $title) {
      if($null -eq (Select-OcrWord $words 'Dashboard' @(60,35,380,90))){throw 'unexpected page before navigation'}
      Assert-ToggleTemplate $Handle
      Send-OwnedPointer $Handle $OwnerPid $origin 32 59 $true $Diagnostic
      Start-Sleep -Milliseconds 600
      $words=@(Read-OwnedOcr $Handle $imagePath $engine);$Diagnostic.last_ocr=$words
      $target=Select-OcrWord $words 'Profiles' @(8,90,230,480)
      if($null -eq $target){throw 'expanded sidebar Profiles label not uniquely recognized'}
      Send-OwnedPointer $Handle $OwnerPid $origin ([int]($target.X+$target.Width/2)) ([int]($target.Y+$target.Height/2)) $true $Diagnostic
      $deadline=[DateTime]::UtcNow.AddSeconds(5)
      do {
        Start-Sleep -Milliseconds 300
        $words=@(Read-OwnedOcr $Handle $imagePath $engine);$Diagnostic.last_ocr=$words
        $title=Select-OcrWord $words 'Profiles' @(60,35,380,90)
      } while($null -eq $title -and [DateTime]::UtcNow -lt $deadline)
      if($null -eq $title){throw 'Profiles page title not observed after navigation'}
    }
    return @{method='owned-window-pointer-ocr';page_title_verified='Profiles';action='profiles';pointer_events=$Diagnostic.pointer_events}
  }
  if($Action -eq 'alternate') {
    if($null -eq $title){throw 'Profile switch requires verified Profiles page'}
    $target=Select-OcrWord $words 'CampaignAlternate' @(230,90,660,550)
    if($null -eq $target){throw 'Alternate profile label is absent or ambiguous'}
    # Pinned ProfileItem CommonCard.onPressed selects this profile.
    # The caller must verify persisted selection AND generated/runtime config.
    Send-OwnedPointer $Handle $OwnerPid $origin ([int]($target.X+$target.Width/2)) ([int]($target.Y+$target.Height/2)) $true $Diagnostic
    return @{method='owned-window-profile-label-ocr';page_title_verified='Profiles';action='alternate';pointer_events=$Diagnostic.pointer_events;result_validation_required=$true}
  }
  if($null -eq $title){throw 'Update requires verified Profiles page'}
  # Move off the toolbar after the previous refresh; verify its neutral appearance.
  # This moves only the cursor, never clicks the neutral point.
  Send-OwnedPointer $Handle $OwnerPid $origin 450 250 $false $Diagnostic
  Start-Sleep -Milliseconds 400
  $words=@(Read-OwnedOcr $Handle $imagePath $engine);$Diagnostic.last_ocr=$words
  if($null -eq (Select-OcrWord $words 'Profiles' @(60,35,380,90))){throw 'page changed before Update'}
  $bitmap=[Drawing.Bitmap]::new($imagePath)
  try {$anchor=Assert-UpdateTemplate $bitmap} finally {$bitmap.Dispose()}
  $Diagnostic.visual_anchor=$anchor
  $Diagnostic.pre_action_png_base64=[Convert]::ToBase64String([IO.File]::ReadAllBytes($imagePath))
  Send-OwnedPointer $Handle $OwnerPid $origin $anchor.target.X $anchor.target.Y $true $Diagnostic
  return @{method='owned-window-template-ocr';page_title_verified='Profiles';action='update';visual_anchor=$anchor;pointer_events=$Diagnostic.pointer_events;pre_action_png_base64=$Diagnostic.pre_action_png_base64;result_validation_required=$true}
}

function New-EnglishOcrEngine {
  Add-Type -AssemblyName System.Runtime.WindowsRuntime
  $null=[Windows.Storage.StorageFile,Windows.Storage,ContentType=WindowsRuntime]
  $null=[Windows.Storage.Streams.IRandomAccessStreamWithContentType,Windows.Storage.Streams,ContentType=WindowsRuntime]
  $null=[Windows.Graphics.Imaging.BitmapDecoder,Windows.Graphics.Imaging,ContentType=WindowsRuntime]
  $null=[Windows.Graphics.Imaging.SoftwareBitmap,Windows.Graphics.Imaging,ContentType=WindowsRuntime]
  $null=[Windows.Media.Ocr.OcrResult,Windows.Media.Ocr,ContentType=WindowsRuntime]
  $null=[Windows.Media.Ocr.OcrEngine,Windows.Media.Ocr,ContentType=WindowsRuntime]
  $language=[Windows.Globalization.Language,Windows.Globalization,ContentType=WindowsRuntime]::new('en-US')
  $engine=[Windows.Media.Ocr.OcrEngine]::TryCreateFromLanguage($language)
  if($null -eq $engine){throw 'English OCR unavailable; no input attempted'}
  return $engine
}

param([string]$OutputRoot = 'dist')
$ErrorActionPreference = 'Stop'
$repoRoot = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
Push-Location $repoRoot
try {
    $revision = (& git rev-parse HEAD).Trim()
    if ($LASTEXITCODE -ne 0) { throw 'Cannot read source revision' }
    $dirty = [bool](& git status --porcelain --untracked-files=normal)
    if ($dirty) { throw 'Commit reviewed source and documentation before packaging' }
    $productRevision = (& git log -1 --format=%H -- cmd internal go.mod go.sum).Trim()
    if ($LASTEXITCODE -ne 0 -or $productRevision -notmatch '^[a-f0-9]{40}$') { throw 'Cannot determine product code revision' }
    & git diff --quiet $productRevision HEAD -- cmd internal go.mod go.sum
    if ($LASTEXITCODE -ne 0) { throw 'Product source differs from recorded revision' }
    $goVersion = & go version
    if ($LASTEXITCODE -ne 0) { throw 'Go is required in PATH' }
    $platform = (& go env GOOS GOARCH) -join '-'
    $label = 'route-agent-0.1.0-dev-' + $platform + '-' + $revision.Substring(0, 12)
    if ($dirty) { $label += '-dirty' }
    if (-not [IO.Path]::IsPathRooted($OutputRoot)) { $OutputRoot = Join-Path $repoRoot $OutputRoot }
    $destination = [IO.Path]::GetFullPath((Join-Path $OutputRoot $label))
    $archive = $destination + '.zip'
    if ((Test-Path -LiteralPath $destination) -or (Test-Path -LiteralPath $archive)) { throw 'Package output already exists' }
    New-Item -ItemType Directory -Path $destination | Out-Null
    $binaryName = 'route-agent'
    if ($platform.StartsWith('windows-')) { $binaryName += '.exe' }
    & go build -trimpath -o (Join-Path $destination $binaryName) ./cmd/route-agent
    if ($LASTEXITCODE -ne 0) { throw 'Build failed' }
    $documents = @(& git ls-files -- '*.md') | Where-Object { -not $_.Contains('/') }
    foreach ($name in @('LICENSE') + $documents) {
        Copy-Item -LiteralPath (Join-Path $repoRoot $name) -Destination $destination
    }
    Copy-Item -LiteralPath (Join-Path $repoRoot 'examples/portable.off.json') -Destination (Join-Path $destination 'config.example.json')
    $examples = Join-Path $destination 'examples'
    New-Item -ItemType Directory -Path $examples | Out-Null
    foreach ($name in @('observation.shadow.json', 'isolated-profile.json', 'isolated-profile.yaml', 'maintenance.template.json', 'portable.off.json')) {
        Copy-Item -LiteralPath (Join-Path (Join-Path $repoRoot 'examples') $name) -Destination $examples
    }
    $evidence = Join-Path $destination 'evidence'
    New-Item -ItemType Directory -Path $evidence | Out-Null
    foreach ($name in @('windows-lifecycle-success-2026-10-08.json', 'windows-tun-mode-2026-10-08.json', 'windows-tun-lifecycle-2026-10-08.json', 'windows-flclash-app-success-2026-10-08.json', 'real-connectivity-policy-2026-10-09.json')) {
        Copy-Item -LiteralPath (Join-Path (Join-Path $repoRoot 'evidence') $name) -Destination $evidence
    }
    $docs = Join-Path $destination 'docs'
    New-Item -ItemType Directory -Path $docs | Out-Null
    foreach ($name in @('POLICY_ACCEPTANCE_DIAGNOSTIC.md', 'ROUTE_INVENTORY_DIAGNOSTIC.md', 'SCHEDULED_PUBLICATION.md')) {
        Copy-Item -LiteralPath (Join-Path (Join-Path $repoRoot 'docs') $name) -Destination $docs
    }
    $manifest = @{version='0.1.0-dev'; revision=$revision; product_code_revision=$productRevision; dirty=$dirty; platform=$platform; go=$goVersion; entry_guide='PORTABLE_QUICKSTART.md'; acceptance_guide='DELIVERY_STATUS.md'; scope='real connectivity passed for two targets; normal probability-threshold refusal; real learning publication unaccepted; historical synthetic evidence is revision-scoped'; lifecycle_tested_sha='39bea08f169d4098fd8884a097b628b03f35f9aa'; lifecycle_run=37753376144; real_connectivity_tested_sha='b4f6f18fbbac6edb83093484934fe8d2e8448f07'; real_connectivity_run=37887426801; real_learning_publication_tested=$false; current_tun_tested=$false; default_controller=''; default_mode='off'; credentials_included=$false}
    $manifest | ConvertTo-Json | Set-Content -Encoding UTF8 -LiteralPath (Join-Path $destination 'manifest.json')
    $hashes = Get-ChildItem -LiteralPath $destination -File -Recurse | Sort-Object FullName | ForEach-Object {
        $relative = $_.FullName.Substring($destination.Length + 1).Replace('\', '/')
        (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant() + '  ' + $relative
    }
    $hashes | Set-Content -Encoding ASCII -LiteralPath (Join-Path $destination 'SHA256SUMS')
    Compress-Archive -LiteralPath $destination -DestinationPath $archive
    ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() + '  ' + [IO.Path]::GetFileName($archive)) | Set-Content -Encoding ASCII -LiteralPath ($archive + '.sha256')
    Write-Output $archive
} finally { Pop-Location }
